def parse_rust_uint(s, maxv):
    """Return (value, kind) where kind None on ok, else Empty/InvalidDigit/PosOverflow."""
    if s == "":
        return None, "Empty"
    i = 0
    if s[0] == '+':
        i = 1
        if len(s) == 1:
            return None, "InvalidDigit"
    val = 0
    for ch in s[i:]:
        if ch < '0' or ch > '9':
            return None, "InvalidDigit"
        d = ord(ch) - 48
        if val > (maxv - d) // 10:
            # check overflow as Rust would when exceeding
            if val * 10 + d > maxv:
                return None, "PosOverflow"
        val = val * 10 + d
        if val > maxv:
            return None, "PosOverflow"
    return val, None

def parse_usize_error_msg(s):
    v, kind = parse_rust_uint(s, 18446744073709551615)
    if kind is None:
        return v, None
    if kind == "Empty":
        return None, "cannot parse integer from empty string"
    if kind == "PosOverflow":
        return None, "number too large to fit in target type"
    return None, "invalid digit found in string"

def fmt_commas(n):
    return f"{n:,}"

def fmt_bytes(n):
    n = int(n) & ((1 << 64) - 1) if n >= 0 else n
    if n < 10000:
        return str(n)
    units = ["K", "M", "G", "T", "P"]
    size = float(n)
    idx = -1
    while size >= 999.5:
        size /= 1000.0
        idx += 1
        if idx >= len(units):
            return "huge"
    if idx < 0:
        return str(n)
    if size < 9.95:
