def round_half_away(x):
    if x >= 0:
        return int(math.floor(x + 0.5))
    return -int(math.floor(-x + 0.5))

def hbar_str(value, max_value, width=20):
    if max_value <= 0 or value <= 0:
        return " " * width
    total_eighths = round_half_away((float(value) / float(max_value)) * width * 8.0)
    if total_eighths > width * 8:
        total_eighths = width * 8
    full = total_eighths // 8
    rem = total_eighths % 8
    parts = "█" * full
    if rem:
        parts += " ▏▎▍▌▋▊▉"[rem]
    if len(parts) < width:
        parts += " " * (width - len(parts))
    return parts

def sparkline_str(values):
