STYLES = {
    None: None,
    "pink": ([("fg", 204)], [("resetfg",)]),
    "pink_bold": ([("fg", 204), ("attr", 1)], [("resetall",)]),
    "pink_bold_underline": ([("fg", 204), ("attr", 1), ("attr", 4)], [("resetall",)]),
    "yellow_bold": ([("fg", 11), ("attr", 1)], [("resetall",)]),
    "yellow": ([("fg", 11)], [("resetfg",)]),
    "gold": ([("fg", 178)], [("resetfg",)]),
    "gray": ([("fg", 239)], [("resetfg",)]),
    "gray240": ([("fg", 240)], [("resetfg",)]),
    "green": ([("fg", 10)], [("resetfg",)]),
    "red": ([("fg", 9)], [("resetfg",)]),
    "code": ([("bg", 235), ("fg", 249)], [("resetbg",), ("resetfg",)]),
    "underline": ([("attr", 4)], [("resetall",)]),
    "progress": ([("bg", 5), ("fg", 11)], [("resetbg",), ("resetfg",)]),
}

class Renderer:
    def __init__(self, colored):
        self.colored = colored
        self.no_color = no_color_env()
        self.width = terminal_width()
    def _code_seq(self, codes):
        out = []
        for c in codes:
            if c[0] == "fg":
                out.append("\x1b[m" if self.no_color else f"\x1b[38;5;{c[1]}m")
            elif c[0] == "bg":
                out.append("\x1b[m" if self.no_color else f"\x1b[48;5;{c[1]}m")
            elif c[0] == "attr":
                out.append(f"\x1b[{c[1]}m")
            elif c[0] == "resetfg":
                out.append("\x1b[m" if self.no_color else "\x1b[39m")
            elif c[0] == "resetbg":
                out.append("\x1b[m" if self.no_color else "\x1b[49m")
            elif c[0] == "resetall":
                out.append("\x1b[0m")
        return ''.join(out)
    def render(self, compounds):
        # compounds: list of (text, style) or plain str
        if isinstance(compounds, str):
            return compounds
        out = []
        for item in compounds:
            if isinstance(item, str):
                out.append(item); continue
            text, style = item
            if not self.colored or style is None:
                out.append(text)
            else:
                start, end = STYLES[style]
                out.append(self._code_seq(start) + text + self._code_seq(end))
        return ''.join(out)
    def print_compounds(self, compounds, end="\n"):
        sys.stdout.write(self.render(compounds) + end)

def C(text, style=None):
    return (text, style)

def plain_text(compounds):
    if isinstance(compounds, str): return compounds
    return ''.join(t for t, s in compounds)

def char_width(ch):
    if ch == '\t':
        return 0
    if unicodedata.combining(ch):
        return 0
    cat = unicodedata.category(ch)
    if cat.startswith('C'):
        return 0
    if unicodedata.east_asian_width(ch) in ('W', 'F'):
        return 2
    return 1

def str_width(s):
    return sum(char_width(c) for c in s)

def compounds_width(compounds):
    return str_width(plain_text(compounds))

def flatten_chars(compounds):
    # list of (char, style)
    if isinstance(compounds, str):
        return [(c, None) for c in compounds]
    out = []
    for text, style in compounds:
        for c in text:
            out.append((c, style))
    return out

def chars_to_compounds(chars):
    if not chars:
        return []
    out = []
    cur_style = chars[0][1]; cur = chars[0][0]
    for c, st in chars[1:]:
        if st == cur_style:
            cur += c
        else:
            out.append((cur, cur_style)); cur = c; cur_style = st
    out.append((cur, cur_style))
    return out

def split_chars_at_width(chars, width):
    """Split list of (char,style) into head with visible width <= width, and rest.
    A wide char that doesn't fit goes to rest."""
    if width <= 0:
        return [], chars
    out = []; w = 0; idx = 0
    while idx < len(chars):
        cw = char_width(chars[idx][0])
        if w + cw > width:
            break
        w += cw; out.append(chars[idx]); idx += 1
    return out, chars[idx:]

def tokenize_words(compounds):
    """Return tokens: ('word', chars) / ('space', chars) where space tokens are runs of ' '."""
    chars = flatten_chars(compounds)
    tokens = []
    i = 0
    while i < len(chars):
        if chars[i][0] == ' ':
            j = i
            while j < len(chars) and chars[j][0] == ' ': j += 1
            tokens.append(('space', chars[i:j])); i = j
        else:
            j = i
            while j < len(chars) and chars[j][0] != ' ': j += 1
            tokens.append(('word', chars[i:j])); i = j
    return tokens

def wrap_paragraph(compounds, width, first_prefix="", rest_prefix=""):
    if width <= 0:
        width = 1
    if compounds_width(compounds) + str_width(first_prefix) <= width:
        # single line, preserve compounds exactly (prefix is plain)
        line = []
        if first_prefix: line.append((first_prefix, None))
        if isinstance(compounds, str): line.append((compounds, None))
        else: line.extend(compounds)
        return [line]
    tokens = tokenize_words(compounds)
    lines = []
    prefix = first_prefix
    cur = []  # chars
    cur_w = str_width(prefix)
    cur_prefix = prefix
    # We will manage prefix separately when emitting
    def emit():
        nonlocal cur, cur_w, cur_prefix
        line = []
        if cur_prefix: line.append((cur_prefix, None))
        line.extend(chars_to_compounds(cur))
        lines.append(line)
        cur = []
        cur_prefix = rest_prefix
        cur_w = str_width(rest_prefix)
    first_token = True
    for kind, tch in tokens:
        if kind == 'space':
            # represent separator as a single space char (first of run) when wrapping
            one = tch[:1]
            if not cur and not first_token:
                # leading space on a new line: skip
                continue
            if cur_w + 1 <= width:
                cur.extend(one); cur_w += 1
            else:
                emit()
            first_token = False
            continue
        # word
        word_w = sum(char_width(c) for c, _ in tch)
        if cur_w + word_w <= width:
            cur.extend(tch); cur_w += word_w
        else:
            if cur:
                emit()
            # now on fresh line
            if word_w + cur_w <= width:
                cur.extend(tch); cur_w += word_w
            else:
                # hard split
                rest = tch
                while rest:
                    avail = width - cur_w
                    if avail <= 0:
                        emit(); avail = width - cur_w
                    head, rest2 = split_chars_at_width(rest, avail)
                    if not head:
                        # a wide char can't fit; force one char
                        head = rest[:1]; rest = rest[1:]
                    else:
                        rest = rest2
                    cur.extend(head); cur_w += sum(char_width(c) for c, _ in head)
                    if rest:
                        emit()
        first_token = False
    # emit last, even if empty
    line = []
    if cur_prefix: line.append((cur_prefix, None))
    line.extend(chars_to_compounds(cur))
    lines.append(line)
    return lines

def wrap_cell(compounds, width, hard=False):
    """Return list of lines (compounds), unpadded."""
    if width <= 0: width = 1
    if compounds_width(compounds) <= width:
        return [compounds if not isinstance(compounds, str) else [(compounds, None)]]
    if hard:
        chars = flatten_chars(compounds)
        lines = []
        rest = chars
        while rest:
            head, rest = split_chars_at_width(rest, width)
            if not head:
                head = rest[:1]; rest = rest[1:]
            lines.append(chars_to_compounds(head))
        return lines if lines else [[("", None)]]
