    tokens = tokenize_words(compounds)
    lines = []
    cur = []; cur_w = 0
    pending_space = None
    def emit():
        nonlocal cur, cur_w
        lines.append(chars_to_compounds(cur)); cur = []; cur_w = 0
    for kind, tch in tokens:
        if kind == 'space':
            if cur:
                pending_space = tch[:1]
            continue
        word_w = sum(char_width(c) for c, _ in tch)
        sep_w = 1 if (cur and pending_space) else 0
        if cur and cur_w + sep_w + word_w <= width:
            if pending_space: cur.extend(pending_space); cur_w += 1
            cur.extend(tch); cur_w += word_w
        else:
            if cur:
                emit()
            # fresh line
            if word_w <= width:
                cur = list(tch); cur_w = word_w
            else:
                rest = tch
                while rest:
                    head, rest = split_chars_at_width(rest, width)
                    if not head:
                        head = rest[:1]; rest = rest[1:]
                    if rest:
                        lines.append(chars_to_compounds(head))
                    else:
                        cur = list(head); cur_w = sum(char_width(c) for c, _ in head)
