        return [[("", None)]]
    if isinstance(cell, str):
        return [[(cell, None)]]
    if isinstance(cell, list) and cell and isinstance(cell[0], tuple):
        return [cell]
    # list of lines
    out = []
    for line in cell:
        if isinstance(line, str): out.append([(line, None)])
        else: out.append(line)
    return out if out else [[("", None)]]

def fit_widths(natural, weights, headers_w, avail):
    n = len(natural)
    if sum(natural) <= avail:
        return list(natural)
    if avail < 3 * n:
        # give 3 each, may exceed; termimad seems to still produce minimums
        return [3] * n
    mins = []
    for i in range(n):
        mins.append(min(natural[i], max(3, min(headers_w[i], 4))))
    total_w = sum(weights) if sum(weights) > 0 else n
    widths = []
    for i in range(n):
        raw = avail * (weights[i] / total_w) if total_w else avail / n
        w = int(math.floor(raw))
        w = max(mins[i], min(natural[i], w))
        widths.append(w)
    # adjust
    guard = 0
    while sum(widths) > avail and guard < 10000:
        guard += 1
        # decrement widest column above its min, prefer largest width then largest natural
        cand = [i for i in range(n) if widths[i] > mins[i]]
        if not cand:
            cand = [i for i in range(n) if widths[i] > 3]
            if not cand: break
        cand.sort(key=lambda i: (widths[i], natural[i], weights[i]), reverse=True)
        widths[cand[0]] -= 1
    guard = 0
    while sum(widths) < avail and guard < 10000:
        guard += 1
        cand = [i for i in range(n) if widths[i] < natural[i]]
        if not cand: break
        # increment column with largest deficit relative to raw allocation / natural
        cand.sort(key=lambda i: ((natural[i] - widths[i]), weights[i]), reverse=True)
        widths[cand[0]] += 1
    return widths

def render_table(renderer, cols, rows, header_style="yellow_bold"):
    """cols: list[Col], rows: list[list[cell]] ; returns list of rendered strings (lines)."""
    term_w = renderer.width
    n = len(cols)
    # natural widths and weights
    natural = []
    weights = []
    headers_w = []
    header_cells = []
    for c in cols:
        # header may be compounds or plain string; if plain string, style it here unless header_style None
        if isinstance(c.header, str):
            hc = [(c.header, header_style)] if header_style else [(c.header, None)]
        else:
            hc = c.header
        header_cells.append(hc)
        headers_w.append(compounds_width(hc))
    # prepare rows logical
    prep_rows = []
    for r in rows:
        prep = []
        for cell in r:
            prep.append(cell_logical_lines(cell))
        prep_rows.append(prep)
    for idx, c in enumerate(cols):
        mx = headers_w[idx]
        tot = headers_w[idx]
        for prep in prep_rows:
            for line in prep[idx]:
                w = compounds_width(line)
                tot += w
                if w > mx: mx = w
        natural.append(max(3, mx))
        weights.append(tot)
    borders = n + 1
    avail = term_w - borders
    if avail < 1: avail = 1
    widths = fit_widths(natural, weights, headers_w, avail) if sum(natural) > avail else list(natural)
    out_lines = []
    def border(left, mid, right):
        comps = []
        comps.append((left, "gray"))
        for i, w in enumerate(widths):
            comps.append(("─" * w, "gray"))
            comps.append(((mid if i < n - 1 else right), "gray"))
        return renderer.render(comps)
    def render_row(cells_compounds_list, aligns, is_header=False):
        # cells_compounds_list: per col, list of logical lines
        wrapped = []
        for idx, c in enumerate(cols):
            wl = []
            for line in cells_compounds_list[idx]:
                wl.extend(wrap_cell(line, widths[idx], hard=c.hard))
            wrapped.append(wl if wl else [[("", None)]])
        height = max(len(wl) for wl in wrapped) if wrapped else 1
        lines = []
        for li in range(height):
            comps = []
            comps.append(("│", "gray"))
            for idx, c in enumerate(cols):
                content = wrapped[idx][li] if li < len(wrapped[idx]) else [("", None)]
                cw = compounds_width(content)
                align = aligns[idx]
                if align == 'r':
                    left_pad = widths[idx] - cw; right_pad = 0
                elif align == 'c':
                    left_pad = (widths[idx] - cw) // 2; right_pad = widths[idx] - cw - left_pad
                else:
                    left_pad = 0; right_pad = widths[idx] - cw
                if left_pad > 0: comps.append((" " * left_pad, None))
                comps.extend(content)
                if right_pad > 0: comps.append((" " * right_pad, None))
                comps.append(("│", "gray"))
            lines.append(renderer.render(comps))
        return lines
    out_lines.append(border("┌", "┬", "┐"))
    header_logical = [[hc] for hc in header_cells]
    out_lines.extend(render_row(header_logical, [c.header_align for c in cols], True))
    out_lines.append(border("├", "┼", "┤"))
    for prep in prep_rows:
        out_lines.extend(render_row(prep, [c.align for c in cols], False))
    out_lines.append(border("└", "┴", "┘"))
    return out_lines

def print_table(renderer, cols, rows, header_style="yellow_bold"):
    for line in render_table(renderer, cols, rows, header_style):
        sys.stdout.write(line + "\n")

def print_paragraph(renderer, compounds, first_prefix="", rest_prefix=""):
    for line in wrap_paragraph(compounds, renderer.width, first_prefix, rest_prefix):
        sys.stdout.write(renderer.render(line) + "\n")

