    # natural widths and weights
    natural = []
    weights = []
    headers_w = []
    header_cells = []
    for c in cols:
        # header may be compounds or plain string; if plain string, style it here unless header_style None
        if isinstance(c.header, str):
            hc = [(c.header, header_style)] if header_style else [(c.header, None)]
        else:
            hc = c.header
        header_cells.append(hc)
        headers_w.append(compounds_width(hc))
    # prepare rows logical
    prep_rows = []
    for r in rows:
        prep = []
        for cell in r:
            prep.append(cell_logical_lines(cell))
        prep_rows.append(prep)
    for idx, c in enumerate(cols):
        mx = headers_w[idx]
