class DateFilter:
    label = "date"
    def __init__(self, raw, ref_date):
        self.raw = raw
        s = raw.strip()
        self.mode = 'eq'
        self.op = None; self.start = None; self.end = None
        if s.startswith('!'):
            self.mode = 'not'; self.op = parse_date_operand(s[1:], ref_date, False)
        elif s.startswith('>'):
            self.mode = 'after'; self.op = parse_date_operand(s[1:], ref_date, False)
        elif s.startswith('<'):
            self.mode = 'before'; self.op = parse_date_operand(s[1:], ref_date, False)
        elif '-' in s:
            parts = s.split('-')
            self.mode = 'range'
            self.start = parse_date_operand(parts[0], ref_date, False)
            # if more than one '-', the second part is used as end (extra ignored), matching a split iterator
            self.end = parse_date_operand(parts[1] if len(parts) > 1 else "", ref_date, False)
        else:
            self.mode = 'eq'; self.op = parse_date_operand(s, ref_date, True)
    def _cmp_op(self, hit, op):
        # return -1/0/1 comparing hit to operand appropriately, or bool eq for period handled elsewhere
        if op.kind == 'date':
            return (hit.date > op.value) - (hit.date < op.value)
        else:
            hv = (hit.date, hit.time)
            return (hv > op.value) - (hv < op.value)
    def accepts(self, hit):
        if self.mode == 'range':
            return self._cmp_op(hit, self.start) >= 0 and self._cmp_op(hit, self.end) <= 0
