        if op.kind == 'yearmonth':
            eq = hit.date[0] == op.value[0] and hit.date[1] == op.value[1]
            return eq
        c = self._cmp_op(hit, op)
        if self.mode == 'eq': return c == 0
        if self.mode == 'not': return c != 0
        if self.mode == 'after': return c > 0
        if self.mode == 'before': return c < 0
        return False

