            p = 0
            for ch in s:
                l = len(ch.encode('utf-8'))
                if p < idx < p + l:
                    panic(loc, f"byte index {idx} is not a char boundary; it is inside {ch!r} (bytes {p}..{p+l}) of `{s}`")
