    if not (0 <= sec <= 59):
        raise RhitError(f"TimeFilter(TimeParse(InvalidSecond({sec})))")
    if not (0 <= minute <= 59):
        raise RhitError(f"TimeFilter(TimeParse(InvalidMinute({minute})))")
    if not (0 <= hour <= 23):
        raise RhitError(f"TimeFilter(TimeParse(InvalidHour({hour})))")
    return (hour, minute, sec)

class TimeFilter:
    label = "time"
    def __init__(self, raw):
        self.raw = raw
        if raw.startswith('>'):
            self.mode = 'after'; self.op = parse_time_fixed(raw[1:].strip())
        elif raw.startswith('<'):
            self.mode = 'before'; self.op = parse_time_fixed(raw[1:].strip())
        else:
            parts = raw.split('-')
            if len(parts) != 2 or parts[0] == "" or parts[1] == "":
                raise RhitError("TimeFilter(InvalidFormat)")
            self.mode = 'range'
            self.start = parse_time_fixed(parts[0].strip())
            self.end = parse_time_fixed(parts[1].strip())
    def accepts(self, hit):
        t = hit.time
        if self.mode == 'after': return t > self.op
        if self.mode == 'before': return t < self.op
        if self.start <= self.end:
            return self.start <= t <= self.end
        else:
            return t >= self.start or t <= self.end

