            parts = item.split('-')
            a = p(parts[0]); b = p(parts[1] if len(parts) > 1 else "")
            return (a, b)
        v = p(item)
        return (v, v)
    def accepts(self, hit):
        s = hit.status
        if self.pos and not any(a <= s <= b for a, b in self.pos):
            return False
        if any(a <= s <= b for a, b in self.neg):
            return False
        return True

