        except OSError as e:
            raise io_os_error(e)
        if is_dir:
            _walk_dir(entry.path, no_name_check, candidates, ancestors)
        else:
            try:
                is_file = entry.is_file(follow_symlinks=True)
            except OSError as e:
                raise io_os_error(e)
            if not is_file:
                continue
            if no_name_check or ("access.log" in entry.name):
                candidates.append(entry.path)

def discover_files(input_paths, no_name_check, is_default):
    candidates = []
    for p in input_paths:
        if not os.path.exists(os.fsencode(p)):
            if is_default:
                pre = "No nginx log found at default location, do you have nginx set up?\nIf necessary, provide the path to the log file(s) as argument.\nMore information with 'rhit --help'.\n"
