            raise RhitError(f"PathNotFound({rust_debug_path(p)})")
        if os.path.isdir(os.fsencode(p)):
            _walk_dir(p, no_name_check, candidates, set())
        else:
            candidates.append(p)
    infos = []
    for cand in candidates:
        first = probe_file(cand)
        if first is not None:
            infos.append(LogFileInfo(cand, first))
    if not infos:
        raise RhitError("NoLogFileFound")
