class Progress:
    def __init__(self, silent, total, input_paths):
        self.silent = silent
        self.total = total
        self.input_paths = input_paths
        self.count = 0
        self._renderer = Renderer(True)
    def _print(self, i):
        if self.silent: return
        bar = hbar_str(i, self.total, 40) if self.total else " " * 40
        seg = self._renderer.render([(bar, "progress")])
        sys.stderr.write(f"\x1b7\x1b[2K{i:4d} / {self.total} {seg}\x1b8")
        try: sys.stderr.flush()
        except Exception: pass
    def start(self):
        self._print(0)
    def inc(self):
        self.count += 1
        self._print(self.count)
    def finish(self):
        if self.silent: return
        noun = "file" if self.total == 1 else "files"
        if len(self.input_paths) == 1:
            where = rust_debug_path(self.input_paths[0])
        else:
            where = "[" + ", ".join(rust_debug_path(p) for p in self.input_paths) + "]"
        sys.stderr.write(f"\x1b7\x1b[2K\x1b8I've read {self.total} {noun} in {where}\n")

