def csv_row(h):
    return f'{fmt_date(h.date)},{fmt_time(h.time)},{h.remote},{h.method},"{h.path}",{h.status},{h.bytes_sent},"{h.referer}"\n'

def json_obj(h):
    return (
        '  {\n'
        f'    "date": "{fmt_date(h.date)}",\n'
        f'    "time": "{fmt_time(h.time)}",\n'
        f'    "remote_addr": "{h.remote}",\n'
        f'    "method": "{h.method}",\n'
        f'    "path": "{h.path}",\n'
        f'    "status": "{h.status}",\n'
        f'    "bytes_sent": {h.bytes_sent},\n'
        f'    "referer": "{h.referer}"\n'
        '  }'
    )

def run_stream(args, infos, filters, input_paths):
    output = args.get("output")
    progress = Progress(args.get("silent_load"), len(infos), input_paths)
    progress.start()
    first_json = True
    if output == "csv":
        sys.stdout.write("date,time,remote address,method,path,status,bytes sent,referer\n")
    elif output == "json":
        sys.stdout.write("[\n")
    for info in infos:
        gen = iter_lines(info.path)
        try:
            for line in gen:
                hit = parse_hit(line, line)
                if hit is None:
                    continue
                ok = True
                for f in filters:
                    if not f.accepts(hit):
                        ok = False; break
                if not ok:
                    continue
                if output == "raw":
                    sys.stdout.write(line)
                elif output == "csv":
                    sys.stdout.write(csv_row(hit))
                elif output == "json":
                    if not first_json:
                        sys.stdout.write(",\n")
                    sys.stdout.write(json_obj(hit))
                    first_json = False
        finally:
            try: gen.close()
            except Exception: pass
        progress.inc()
    progress.finish()
    if output == "json":
        sys.stdout.write("\n]\n" if not first_json else "]\n")

