        gen = iter_lines(info.path)
        try:
            for line in gen:
                hit = parse_hit(line, "")
                if hit is not None:
                    hits.append(hit)
        finally:
            try: gen.close()
            except Exception: pass
        progress.inc()
    progress.finish()
    if not hits:
        where = "[" + ", ".join(rust_debug_path(p) for p in input_paths) + "]"
        raise RhitError(f"NoHitInPaths({where})")
    total_hits = len(hits)
