def build_filters(args, ref_date):
    filters = []
    if args.get("date") is not None: filters.append(DateFilter(args["date"], ref_date))
    if args.get("ip") is not None: filters.append(IpFilter(args["ip"]))
    if args.get("method") is not None: filters.append(MethodFilter(args["method"]))
