    return any(0xDC80 <= ord(c) <= 0xDCFF for c in s)

def _jaro(s1, s2):
    if s1 == s2: return 1.0
    len1, len2 = len(s1), len(s2)
    if len1 == 0 or len2 == 0: return 0.0
    match_dist = max(len1, len2) // 2 - 1
    if match_dist < 0: match_dist = 0
    s1_matches = [False]*len1; s2_matches = [False]*len2
    matches = 0
