    if match_dist < 0: match_dist = 0
    s1_matches = [False]*len1; s2_matches = [False]*len2
    matches = 0
    for i in range(len1):
        start = max(0, i - match_dist); end = min(i + match_dist + 1, len2)
        for j in range(start, end):
            if not s2_matches[j] and s1[i] == s2[j]:
                s1_matches[i] = True; s2_matches[j] = True; matches += 1; break
    if matches == 0: return 0.0
    k = 0; trans = 0
    for i in range(len1):
        if s1_matches[i]:
            while not s2_matches[k]: k += 1
            if s1[i] != s2[k]: trans += 1
            k += 1
    trans /= 2
    return (matches/len1 + matches/len2 + (matches-trans)/matches) / 3

def _jaro_winkler(s1, s2):
    j = _jaro(s1, s2)
    prefix = 0
    for a, b in zip(s1, s2):
        if a == b and prefix < 4: prefix += 1
        else: break
    if j > 0.7:
        j += prefix * 0.1 * (1-j)
    return min(j, 1.0)

def did_you_mean(value, candidates, with_dashes=False):
    best = None; best_score = 0.0
    v = ("--" + value) if with_dashes and not value.startswith("--") else value
    for cand in candidates:
        c = ("--" + cand) if with_dashes else cand
        score = _jaro_winkler(v, c)
        if score > best_score or (abs(score-best_score) < 1e-12 and (best is None or cand < best)):
            best_score = score; best = cand
    if best is not None and best_score > 0.7:
        return best
    return None

def parse_fields_value(s):
    fields = ["date", "status", "ref", "path"] if s[:1] in ('+', '-') else []
    ALL = ["date", "time", "method", "status", "ip", "ref", "path"]
    mp = {'d':"date",'t':"time",'m':"method",'s':"status",'i':"ip",'r':"ref",'p':"path",'a':"all"}
    op_add = True
    expecting = True
    i = 0
    def apply_one(fname, add):
        if fname == "all":
            for f in ALL: apply_one(f, add)
            return
        if fname in fields: fields.remove(fname)
        if add: fields.append(fname)
    while i < len(s):
        c = s[i]
        if expecting:
            if c == '+': op_add = True; i += 1; continue
            if c == '-': op_add = False; i += 1; continue
            if c == ',' or c == ' ': op_add = True; i += 1; continue
            lc = chr(ord(c)+32) if 'A' <= c <= 'Z' else c
            if lc not in mp:
                raise ValueError(lc)
            apply_one(mp[lc], op_add)
            expecting = False; i += 1; continue
        else:
            if c == '+': op_add = True; expecting = True; i += 1; continue
            if c == '-': op_add = False; expecting = True; i += 1; continue
            if c == ',' or c == ' ': op_add = True; expecting = True; i += 1; continue
            i += 1; continue
    return fields

class ArgParser:
    def __init__(self, argv):
        self.argv = argv
        prog = argv[0] if argv else "rhit"
        base = os.path.basename(prog)
        self.bin = lossy(base) if base else lossy(prog)
        self.seen = {}
        self.used_order = []
        self.positional_seen = False
        self.args = {
            "help": False, "version": False, "color": "auto", "key": "hits", "length": 1,
            "fields": ["date", "status", "ref", "path"], "changes": False,
            "date": None, "ip": None, "method": None, "path": None, "referer": None, "status": None, "time": None,
            "all": False, "no_name_check": False, "output": "tables", "silent_load": False,
            "files": [],
        }
    def frag(self, spec):
        return f"--{spec.long} <{spec.value}>" if spec.value else f"--{spec.long}"
    def generic_usage(self):
        return f"Usage: {self.bin} [OPTIONS] [FILES]...\n"
    def used_usage(self, extra=None):
        parts = [self.frag(s) for s in self.used_order]
        if extra is not None and extra.id not in self.seen:
            parts.append(self.frag(extra))
        if not parts and not self.positional_seen:
            return self.generic_usage()
        tail = "<FILES>..." if self.positional_seen else "[FILES]..."
        allp = parts + [tail]
        return f"Usage: {self.bin} " + " ".join(allp) + "\n"
    def err_unknown_long(self, display):
        # display includes leading dashes, lossy
        name = display[2:] if display.startswith("--") else display
        cand = did_you_mean(display, [o.long for o in OPT_SPECS], with_dashes=True)
        if cand:
            spec = LONG_MAP[cand]
            txt = f"error: unexpected argument '{display}' found\n\n  tip: a similar argument exists: '--{cand}'\n\n" + self.used_usage(spec)
        else:
            txt = f"error: unexpected argument '{display}' found\n\n  tip: to pass '{display}' as a value, use '-- {display}'\n\n" + self.used_usage()
        raise ClapError(txt)
    def err_unknown_short(self, ch):
        disp = "-" + lossy(ch)
        txt = f"error: unexpected argument '{disp}' found\n\n  tip: to pass '{disp}' as a value, use '-- {disp}'\n\n" + self.generic_usage()
        raise ClapError(txt)
    def err_missing(self, spec):
        txt = f"error: a value is required for '{self.frag(spec)}' but none was supplied\n"
        if spec.id == "color":
            txt += "  [possible values: auto, yes, no]\n"
        raise ClapError(txt)
    def err_repeated(self, spec):
        raise ClapError(f"error: the argument '{self.frag(spec)}' cannot be used multiple times\n\n" + self.generic_usage())
    def err_invalid(self, spec, value, msg):
        raise ClapError(f"error: invalid value '{lossy(value)}' for '{self.frag(spec)}': {msg}\n")
    def err_invalid_utf8(self):
        raise ClapError("error: invalid UTF-8 was detected in one or more arguments\n\n" + self.generic_usage())
    def err_unexpected_value(self, spec, value):
        if self.used_order:
            all_frags = [self.frag(o) for o in OPT_SPECS] + ["FILES"]
            usage = f"Usage: {self.bin} <" + "|".join(all_frags) + ">\n"
        else:
            usage = f"Usage: {self.bin} {self.frag(spec)} [FILES]...\n"
        raise ClapError(f"error: unexpected value '{lossy(value)}' for '--{spec.long}' found; no more were expected\n\n" + usage)
    def _is_recognized_option_token(self, tok):
        if tok.startswith("--"):
            name = tok[2:].split('=', 1)[0]
            return name in LONG_MAP
        if tok.startswith("-") and len(tok) > 1:
            return tok[1] in SHORT_MAP
        return False
    def obtain_value(self, spec, i):
        # i is index of option token in argv list (self.tokens)
        if i + 1 >= len(self.tokens):
            self.err_missing(spec)
        nxt = self.tokens[i+1]
        if nxt == "--":
            self.err_missing(spec)
        if nxt == "-" or nxt == "" or not nxt.startswith("-"):
            return nxt, i + 1
        # starts with '-'
        if nxt.startswith("--"):
            name = nxt[2:].split('=', 1)[0]
            if name in LONG_MAP:
                self.err_missing(spec)
            else:
                self.err_unknown_long(lossy(nxt.split('=', 1)[0]))
        else:
            ch = nxt[1] if len(nxt) > 1 else ""
            if ch in SHORT_MAP:
                self.err_missing(spec)
            else:
                self.err_unknown_short(ch)
        self.err_missing(spec)
    def process_value(self, spec, value):
        # repeat already checked by caller before validation (except color empty handled by caller)
        if has_surrogate(value):
            if spec.id == "color":
                self._validate_color(lossy(value)); return
            self.err_invalid_utf8()
        if spec.id == "color":
            self._validate_color(value); return
        if spec.id == "key":
            lv = value.lower()
            if lv in ("h", "hit", "hits"):
                self.args["key"] = "hits"
            elif lv in ("b", "byte", "bytes"):
                self.args["key"] = "bytes"
            else:
                self.err_invalid(spec, value, f"unrecognized key {rust_debug_str(value)}")
            return
        if spec.id == "output":
            lv = value.lower()
            mp = {"t":"tables","tables":"tables","r":"raw","raw":"raw","c":"csv","csv":"csv","j":"json","json":"json"}
            if lv in mp: self.args["output"] = mp[lv]
            else: self.err_invalid(spec, value, f"unrecognized output {rust_debug_str(value)}")
            return
        if spec.id == "length":
            v, msg = parse_usize_error_msg(value)
            if msg: self.err_invalid(spec, value, msg)
            self.args["length"] = v; return
        if spec.id == "fields":
            try:
                self.args["fields"] = parse_fields_value(value)
            except ValueError as e:
                ch = str(e)
                self.err_invalid(spec, value, f"unrecognized field start '{ch}'")
            return
        self.args[spec.id] = value
    def _validate_color(self, value):
        if value in ("auto", "yes", "no"):
            self.args["color"] = value; return
        cand = did_you_mean(value, ["auto", "yes", "no"])
        txt = f"error: invalid value '{lossy(value)}' for '--color <color>'\n  [possible values: auto, yes, no]\n"
        if cand:
            txt += f"\n  tip: a similar value exists: '{cand}'\n"
        raise ClapError(txt)
    def handle_value_option(self, spec, value, new_index):
        # color empty behaves as missing
        if spec.id == "color" and value == "":
            self.err_missing(spec)
        if spec.id in self.seen:
            self.err_repeated(spec)
        self.seen[spec.id] = True
        self.used_order.append(spec)
        self.process_value(spec, value)
        return new_index
    def handle_flag(self, spec):
        if spec.id in self.seen:
            self.err_repeated(spec)
        self.seen[spec.id] = True
        self.used_order.append(spec)
        self.args[spec.id] = True
    def parse(self):
        self.tokens = self.argv[1:]
        i = 0; only_pos = False
        while i < len(self.tokens):
            tok = self.tokens[i]
            if only_pos or tok == "-" or tok == "" or not tok.startswith("-"):
                self.args["files"].append(tok); self.positional_seen = True; i += 1; continue
            if tok == "--":
                only_pos = True; i += 1; continue
            if tok.startswith("--"):
                body = tok[2:]
                if "=" in body:
                    name, val_eq = body.split("=", 1)
                else:
                    name, val_eq = body, None
                spec = LONG_MAP.get(name)
                if spec is None:
                    self.err_unknown_long(lossy(tok.split("=", 1)[0]))
                if spec.value is None:
                    if val_eq is not None:
                        self.err_unexpected_value(spec, val_eq)
                    self.handle_flag(spec); i += 1; continue
                else:
                    if val_eq is not None:
                        self.handle_value_option(spec, val_eq, i); i += 1; continue
                    value, ni = self.obtain_value(spec, i)
                    self.handle_value_option(spec, value, ni); i = ni + 1; continue
            else:
                # short cluster
                pos = 1
                consumed_next = False
                while pos < len(tok):
                    ch = tok[pos]
                    spec = SHORT_MAP.get(ch)
                    if spec is None:
                        self.err_unknown_short(ch)
                    if spec.value is None:
                        self.handle_flag(spec); pos += 1; continue
                    else:
                        rest = tok[pos+1:]
                        if rest != "":
                            value = rest[1:] if rest.startswith("=") else rest
                            self.handle_value_option(spec, value, i)
                        else:
                            value, ni = self.obtain_value(spec, i)
                            self.handle_value_option(spec, value, ni); consumed_next = True
                        pos = len(tok); break
                i = i + 2 if consumed_next else i + 1
                continue
        return self.args

# ---------- help ----------
def md_inline(s):
    parts = s.split('`')
    out = []
    for idx, part in enumerate(parts):
        if part == "" and idx not in (0, len(parts)-1):
            pass
        out.append((part, "code" if idx % 2 == 1 else None))
    return out

def print_help(renderer):
    # title centered
    title_text = "rhit 2.0.4"
    pad = max(0, (renderer.width - str_width(title_text)) // 2)
