    print_paragraph(renderer, [("Usage: ", "pink_bold"), (" ", None), ("rhit", "code"), (" [options]", "code"), (" [FILES]", "code")])
    sys.stdout.write("\n")
    print_paragraph(renderer, [("•", "gray240"), (" ", None), ("FILES", "code"), (" : The log file or folder to analyze. It not provided, logs will be opened at their standard location", None)], rest_prefix="  ")
    sys.stdout.write("\n")
    print_paragraph(renderer, [("Options:", "pink_bold")])
    rows_data = [
        ("", "--help", "", ["Print help information"]),
        ("", "--version", "", ["Print the version"]),
        ("", "--color", "color", ["Whether to have styles and colors", " Possible values: [`auto`, `yes`, `no`]", " Default: `auto`"]),
