        ("", "--silent-load", "", ["Don't print anything during load: no progress bar or file list"]),
    ]
    cols = [Col("short", 'c'), Col("long", 'l', header_align='c'), Col("value", 'c'), Col("description", 'l')]
    rows = []
    for short, longn, val, descs in rows_data:
        short_txt = f" -{short} " if short else ""
        rows.append([
