        ])
    print_table(renderer, cols, rows, header_style=None)
    sys.stdout.write("\n")

# ---------- main ----------
def build_filters(args, ref_date):
    filters = []
    if args.get("date") is not None: filters.append(DateFilter(args["date"], ref_date))
    if args.get("ip") is not None: filters.append(IpFilter(args["ip"]))
    if args.get("method") is not None: filters.append(MethodFilter(args["method"]))
    if args.get("path") is not None: filters.append(PathFilter(args["path"]))
    if args.get("referer") is not None: filters.append(RefererFilter(args["referer"]))
    if args.get("status") is not None: filters.append(StatusFilter(args["status"]))
    if args.get("time") is not None: filters.append(TimeFilter(args["time"]))
    return filters

def main(argv):
    try:
        try:
            sys.stdout.reconfigure(line_buffering=True)
        except Exception:
            pass
        parser = ArgParser(argv)
        args = parser.parse()
        if args.get("version"):
            sys.stdout.write("rhit 2.0.4\n")
            return 0
        if args.get("help"):
            renderer = Renderer(True)
            print_help(renderer)
            return 0
        input_paths = args["files"] if args["files"] else ["/var/log/nginx"]
        is_default = not bool(args["files"])
        infos = discover_files(input_paths, args.get("no_name_check"), is_default)
        ref_date = infos[0].first_hit.date if infos else (1970, 1, 1)
        filters = build_filters(args, ref_date)
        if args.get("output") == "tables":
            colored = args.get("color") == "yes" or (args.get("color") == "auto" and sys.stdout.isatty())
            renderer = Renderer(colored)
            run_tables(args, infos, filters, renderer, input_paths)
        else:
            run_stream(args, infos, filters, input_paths)
        try:
            sys.stdout.flush()
        except BrokenPipeError:
            raise
        return 0
    except ClapError as e:
        sys.stderr.write(e.text)
        return 2
    except PanicError as e:
        try:
            os.write(2, f"\nthread 'main' ({os.getpid()}) panicked at {e.location}:\n{e.message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n".encode('utf-8', 'replace'))
        except Exception:
            pass
        return 101
    except RhitError as e:
        if e.pre:
            sys.stderr.write(e.pre)
        sys.stderr.write(f"Error: {e.debug}\n")
        return 1
    except BrokenPipeError:
        try:
            os.write(2, f"\nthread 'main' ({os.getpid()}) panicked at library/std/src/io/stdio.rs:1165:9:\nfailed printing to stdout: Broken pipe (os error 32)\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n".encode())
        except Exception:
            pass
        return 101

if __name__ == "__main__":
    sys.exit(main(sys.argv))
