new=r'''class _GzipFirstMember:
    """Read only the first gzip member, like flate2's GzDecoder."""
    def __init__(self, rawf):
        self.rawf = rawf
        self.obj = zlib.decompressobj(-15)
        self.buf = b""
        self.eof = False
        self._state = 'header'
        self._inbuf = b""
        self._crc = 0
        self._isize = 0
        self._pending_error = None
    def _read_more(self):
        chunk = self.rawf.read(8192)
        if chunk:
            self._inbuf += chunk
            return True
        return False
    def _ensure(self, n):
        while len(self._inbuf) < n:
            if not self._read_more():
                raise io_kind("UnexpectedEof")
    def _parse_header(self):
        self._ensure(10)
        hdr = self._inbuf
        if hdr[0] != 0x1f or hdr[1] != 0x8b or hdr[2] != 0x08 or (hdr[3] & 0xE0):
            raise io_custom("InvalidInput", "invalid gzip header")
        flags = hdr[3]
        pos = 10
        if flags & 0x04:  # FEXTRA
            self._ensure(pos + 2)
            xlen = self._inbuf[pos] | (self._inbuf[pos+1] << 8)
            pos += 2
            self._ensure(pos + xlen)
            pos += xlen
        if flags & 0x08:  # FNAME
            while True:
                z = self._inbuf.find(b"\0", pos)
                if z >= 0:
                    pos = z + 1; break
                if not self._read_more():
                    raise io_kind("UnexpectedEof")
        if flags & 0x10:  # FCOMMENT
            while True:
                z = self._inbuf.find(b"\0", pos)
                if z >= 0:
                    pos = z + 1; break
                if not self._read_more():
                    raise io_kind("UnexpectedEof")
        if flags & 0x02:  # FHCRC
            self._ensure(pos + 2)
            stored = self._inbuf[pos] | (self._inbuf[pos+1] << 8)
            if (zlib.crc32(self._inbuf[:pos]) & 0xFFFF) != stored:
                raise io_custom("InvalidInput", "invalid gzip header")
            pos += 2
        self._inbuf = self._inbuf[pos:]
        self._state = 'body'
    def _finish_footer(self):
        # self._inbuf currently holds unused_data after deflate stream
        try:
            while len(self._inbuf) < 8:
                if not self._read_more():
                    raise io_kind("UnexpectedEof")
            crc_stored = int.from_bytes(self._inbuf[0:4], 'little')
            isize_stored = int.from_bytes(self._inbuf[4:8], 'little')
            if crc_stored != (self._crc & 0xFFFFFFFF) or isize_stored != (self._isize & 0xFFFFFFFF):
                raise io_custom("InvalidInput", "corrupt gzip stream does not have a matching checksum")
        except RhitError as e:
            self._pending_error = e
        self.eof = True
    def _fill(self):
        if self.eof:
            return False
        if self._state == 'header':
            self._parse_header()
        # body
        data = self._inbuf; self._inbuf = b""
        if not data:
            data = self.rawf.read(8192)
            if not data:
                raise io_kind("UnexpectedEof")
        try:
            out = self.obj.decompress(data)
        except zlib.error:
            raise io_custom("InvalidInput", "invalid deflate stream")
        self.buf += out
        self._crc = zlib.crc32(out, self._crc)
        self._isize += len(out)
        if self.obj.eof:
            self._inbuf = self.obj.unused_data
            self._finish_footer()
        return True
    def readline(self):
        while b'\n' not in self.buf and not self.eof:
            self._fill()
        idx = self.buf.find(b'\n')
        if idx >= 0:
            line = self.buf[:idx+1]; self.buf = self.buf[idx+1:]
            return line
        if self.buf:
            line = self.buf; self.buf = b""
            return line
        if self._pending_error is not None:
            err = self._pending_error; self._pending_error = None
            raise err
        return b""
    def close(self):
        pass

'''
